<div class="wrap">
  <header>
    <h1>My Bookmarks</h1>
    <p>A calm place to save links and find them again.</p>
  </header>

  <div class="save-bar">
    <input id="urlInput" type="text" placeholder="Paste a link to save…" autocomplete="off" />
    <button class="btn" id="saveBtn">Save</button>
  </div>
  <div class="flash" id="flash"></div>

  <div class="list" id="list"></div>
</div>

<div class="overlay" id="overlay">
  <div class="modal">
    <h2 id="modalTitle">Save this link</h2>
    <p class="hint" id="modalHint">We filled in the details from the page. Adjust anything you like.</p>

    <div class="preview-row">
      <div id="mThumb">…</div>
      <div>
        <div style="display:flex; align-items:center; gap:8px;">
          <div id="mFav">…</div>
          <span class="preview-cap" id="previewCap">reading the page…</span>
        </div>
      </div>
    </div>

    <div class="field">
      <label>Title</label>
      <input id="fTitle" type="text" />
      <div class="auto" id="titleAuto">✓ filled in for you</div>
    </div>
    <div class="field">
      <label>Description</label>
      <textarea id="fDesc"></textarea>
      <div class="auto" id="descAuto">✓ filled in for you</div>
    </div>

    <div class="toggle-row">
      <div class="switch on" id="rlSwitch"><div class="knob"></div></div>
      <div>
        <div class="t-text">Read later</div>
        <div class="t-sub">Keep it in your "still to read" pile</div>
      </div>
    </div>

    <div class="field">
      <label>Your note (optional)</label>
      <textarea id="fNote" placeholder="Why is this worth keeping?"></textarea>
    </div>
    <div class="field">
      <label>Labels</label>
      <input id="fTags" type="text" placeholder="e.g. reading, work" />
      <div class="suggest" id="suggest"></div>
    </div>

    <div class="actions">
      <button class="btn secondary" id="cancelBtn">Cancel</button>
      <button class="btn" id="confirmBtn">Save to my list</button>
    </div>
  </div>
</div>

<script>
  // --- simulated "fetch page details" (prototype only; real app reads the live page) ---
  const SAMPLES = {
    "smashingmagazine.com": { title: "Designing Calm Interfaces — Smashing Magazine", desc: "Principles for building software that respects a user's attention.", preview: "Calm Interfaces" },
    "developer.mozilla.org": { title: "Array.prototype.reduce() — JavaScript | MDN", desc: "The reduce() method executes a reducer function on each array element, resulting in a single value.", preview: "MDN Web Docs" },
    "nytimes.com": { title: "The Quiet Power of Reading Slowly — The New York Times", desc: "Why unhurried reading may be the antidote to information overload.", preview: "The New York Times" },
    "en.wikipedia.org": { title: "Spaced repetition — Wikipedia", desc: "A learning technique using increasing intervals between reviews of learned material.", preview: null },
    "github.com": { title: "sindresorhus/awesome — curated list of awesome lists", desc: "A community-driven collection of awesome resources on many topics.", preview: "GitHub" }
  };
  const PALETTE = ["#4a6b57","#7a5c8a","#b5713f","#3f6f8a","#8a4a58","#5a7a3f","#8a7a3f"];
  function normUrl(u){ return u.trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/+$/,''); }
  function domainOf(url){ try { return new URL(url.match(/^https?:\/\//)? url : "https://"+url).hostname.replace(/^www\./,''); } catch(e){ return ""; } }
  function colorFor(s){ let h=0; for(const c of (s||"x")) h=(h*31+c.charCodeAt(0))>>>0; return PALETTE[h%PALETTE.length]; }
  function monogram(d){ const base=(d||"?").replace(/^www\./,''); return (base[0]||"?").toUpperCase(); }
  function titleCaseFromDomain(d){ const base=(d||"").split(".")[0]; return base? base.charAt(0).toUpperCase()+base.slice(1)+" — saved page" : "Untitled page"; }
  function fetchDetails(url){
    const d = domainOf(url);
    const s = SAMPLES[d];
    if (s) return { title:s.title, desc:s.desc, preview:s.preview, domain:d, auto:true };
    return { title: titleCaseFromDomain(d), desc:"", preview:null, domain:d, auto: !!d };
  }

  // --- state ---
  let bookmarks = JSON.parse(localStorage.getItem("bm_proto_v2")||"[]");
  let pending = null;      // {url, domain, preview}
  let editingId = null;    // id of existing bookmark when updating a duplicate
  let readLater = true;
  function save(){ localStorage.setItem("bm_proto_v2", JSON.stringify(bookmarks)); }
  function knownTags(){ const t=new Set(); bookmarks.forEach(b=>(b.tags||[]).forEach(x=>t.add(x))); return [...t]; }

  const listEl = document.getElementById("list");
  function render(){
    if(!bookmarks.length){
      listEl.innerHTML = '<div class="empty"><div class="big">Nothing saved yet.</div><div>Paste a link above to keep your first one.</div></div>';
      return;
    }
    listEl.innerHTML = bookmarks.map(b => {
      const col = colorFor(b.domain||b.url);
      const thumb = b.preview
        ? `<div class="thumb" style="background:linear-gradient(135deg,${col},${shade(col)})">${esc(b.preview)}</div>`
        : `<div class="thumb" style="background:#eceae4;color:#b7b5ad">no preview</div>`;
      return `
      <div class="item" id="item-${b.id}">
        ${thumb}
        <div class="body">
          <div class="titleline">
            <div class="favicon" style="background:${col}">${esc(monogram(b.domain))}</div>
            <p class="title">${esc(b.title)}</p>
          </div>
          ${b.desc? `<p class="desc">${esc(b.desc)}</p>`:""}
          <div class="chips">
            ${b.readLater? `<span class="badge">Read later</span>`:""}
            ${(b.tags||[]).map(t=>`<span class="chip">${esc(t)}</span>`).join("")}
          </div>
          <p class="url">${esc(b.url)}</p>
          ${b.note? `<p class="note">“${esc(b.note)}”</p>`:""}
        </div>
      </div>`; }).join("");
  }
  function shade(hex){ return hex; }
  function esc(s){ return (s||"").replace(/[&<>"]/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])); }

  // --- flash message ---
  const flashEl = document.getElementById("flash");
  function flash(msg){ flashEl.textContent=msg; flashEl.classList.add("show"); setTimeout(()=>flashEl.classList.remove("show"), 4000); }

  // --- save / update flow ---
  const overlay = document.getElementById("overlay");
  const urlInput = document.getElementById("urlInput");
  const rlSwitch = document.getElementById("rlSwitch");
  document.getElementById("saveBtn").onclick = startSave;
  urlInput.addEventListener("keydown", e=>{ if(e.key==="Enter") startSave(); });
  rlSwitch.onclick = ()=>{ readLater=!readLater; rlSwitch.classList.toggle("on", readLater); };

  function setSwitch(v){ readLater=v; rlSwitch.classList.toggle("on", v); }

  function renderSuggest(){
    const box=document.getElementById("suggest");
    const current=document.getElementById("fTags").value.split(",").map(s=>s.trim().toLowerCase()).filter(Boolean);
    const opts=knownTags().filter(t=>!current.includes(t.toLowerCase()));
    box.innerHTML = opts.length? `<span class="s-label">Labels you've used:</span>`+opts.map(t=>`<span class="chip" data-t="${esc(t)}">${esc(t)}</span>`).join("") : "";
    box.querySelectorAll(".chip").forEach(c=> c.onclick=()=>{
      const f=document.getElementById("fTags");
      const arr=f.value.split(",").map(s=>s.trim()).filter(Boolean); arr.push(c.dataset.t);
      f.value=arr.join(", "); renderSuggest();
    });
  }
  document.getElementById("fTags").addEventListener("input", renderSuggest);

  function startSave(){
    const url = urlInput.value.trim();
    if(!url) return;
    const key = normUrl(url);
    const existing = bookmarks.find(b=>normUrl(b.url)===key);
    if(existing){ openEdit(existing); return; }

    editingId = null;
    pending = { url, domain: domainOf(url), preview:null };
    document.getElementById("modalTitle").textContent = "Save this link";
    document.getElementById("modalHint").textContent = "Reading the page…";
    document.getElementById("fTitle").value = "…";
    document.getElementById("fDesc").value = "";
    document.getElementById("fNote").value = "";
    document.getElementById("fTags").value = "";
    setSwitch(true);
    document.getElementById("confirmBtn").textContent = "Save to my list";
    paintPreview(null, pending.domain, "reading the page…");
    document.getElementById("titleAuto").style.display="none";
    document.getElementById("descAuto").style.display="none";
    renderSuggest();
    overlay.classList.add("open");
    setTimeout(()=>{
      const d = fetchDetails(url);
      pending.preview = d.preview; pending.domain=d.domain;
      document.getElementById("fTitle").value = d.title;
      document.getElementById("fDesc").value = d.desc;
      document.getElementById("modalHint").textContent = "We filled in the details from the page. Adjust anything you like.";
      document.getElementById("titleAuto").style.display = d.auto? "block":"none";
      document.getElementById("descAuto").style.display = d.desc? "block":"none";
      paintPreview(d.preview, d.domain, d.preview? "preview image + site icon collected" : "site icon collected (no preview image on this page)");
    }, 650);
  }

  function openEdit(b){
    editingId = b.id;
    pending = { url:b.url, domain:b.domain, preview:b.preview };
    document.getElementById("modalTitle").textContent = "You already saved this";
    document.getElementById("modalHint").textContent = "Here's the one you saved before — update anything you like.";
    document.getElementById("fTitle").value = b.title;
    document.getElementById("fDesc").value = b.desc||"";
    document.getElementById("fNote").value = b.note||"";
    document.getElementById("fTags").value = (b.tags||[]).join(", ");
    setSwitch(!!b.readLater);
    document.getElementById("confirmBtn").textContent = "Update";
    document.getElementById("titleAuto").style.display="none";
    document.getElementById("descAuto").style.display="none";
    paintPreview(b.preview, b.domain, "already in your list");
    renderSuggest();
    overlay.classList.add("open");
  }

  function paintPreview(preview, domain, cap){
    const col=colorFor(domain||"x");
    const t=document.getElementById("mThumb");
    if(preview){ t.style.background=`linear-gradient(135deg,${col},${col})`; t.style.color="#fff"; t.textContent=preview; }
    else { t.style.background="#eceae4"; t.style.color="#b7b5ad"; t.textContent="no preview"; }
    const f=document.getElementById("mFav"); f.style.background=col; f.textContent=monogram(domain);
    document.getElementById("previewCap").textContent=cap;
  }

  document.getElementById("cancelBtn").onclick = ()=> overlay.classList.remove("open");
  document.getElementById("confirmBtn").onclick = ()=>{
    const tags = document.getElementById("fTags").value.split(",").map(s=>s.trim()).filter(Boolean);
    const data = {
      url: pending.url,
      domain: pending.domain,
      preview: pending.preview,
      title: document.getElementById("fTitle").value.trim() || pending.url,
      desc: document.getElementById("fDesc").value.trim(),
      note: document.getElementById("fNote").value.trim(),
      tags: tags,
      readLater: readLater
    };
    if(editingId){
      const i=bookmarks.findIndex(b=>b.id===editingId);
      if(i>=0) bookmarks[i]={...bookmarks[i], ...data};
      save(); render(); overlay.classList.remove("open");
      flash("Updated your saved link.");
      highlight(editingId);
    } else {
      data.id = Date.now();
      bookmarks.unshift(data);
      save(); render(); overlay.classList.remove("open");
      urlInput.value="";
    }
  };
  function highlight(id){ const el=document.getElementById("item-"+id); if(el){ el.scrollIntoView({behavior:"smooth",block:"center"}); el.classList.add("flash-hit"); setTimeout(()=>el.classList.remove("flash-hit"),1600); } }

  render();
  document.body.setAttribute("data-harness-ready","true");
</script>
</body>
